using System;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Threading;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using FrameCut;
class MultiUiSmoke {
 static string root,dir,report,picture;static int checks;static Window window;static object controller;
 static object Field(string name){return typeof(Controller).GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(controller);}
 static Project Project{get{return (Project)Field("project");}}static MediaInfo Media{get{return (MediaInfo)Field("media");}}
 static T Find<T>(string name)where T:class{return window.FindName(name)as T;}
 static void Check(bool ok,string name){if(!ok)throw new Exception("FAIL: "+name);checks++;File.AppendAllText(report,"PASS "+name+Environment.NewLine);}
 static void Click(string name){Find<Button>(name).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));}
 static double Rms(byte[] raw,int start,int length){double sum=0;for(int i=start;i<start+length;i++){short v=(short)(raw[2*i]|raw[2*i+1]<<8);sum+=(double)v*v;}return Math.Sqrt(sum/length);}
 static double Frequency(byte[] raw,int start,int length){int n=0;for(int i=start+1;i<start+length;i++){short a=(short)(raw[2*i-2]|raw[2*i-1]<<8),b=(short)(raw[2*i]|raw[2*i+1]<<8);if(a<0&&b>=0)n++;}return n*48000.0/length;}
 static async Task Until(Func<bool> f){DateTime end=DateTime.UtcNow.AddSeconds(40);while(!f()){if(DateTime.UtcNow>end)throw new Exception("Timed out waiting for UI state");await Task.Delay(60);}}
 static async Task Jump(int frame){Find<TextBox>("JumpFrame").Text=frame.ToString();Click("Jump");await Until(()=>Find<Border>("DecodeBadge").Visibility==Visibility.Collapsed&&Find<TextBlock>("PreviewTag").Text.EndsWith("第 "+frame+" 帧"));}
 static async Task Open(string path){typeof(Controller).GetField("dirty",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(controller,false);await(Task)typeof(Controller).GetMethod("OpenPath",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(controller,new object[]{path});}
 [STAThread]static void Main(string[]args){RunMain(args);}
 [STAThread]public static void RunMain(string[]args){root=Path.GetFullPath(args[0]);dir=Path.GetFullPath(args[1]);report=Path.GetFullPath(args[2]);picture=Path.GetFullPath(args[3]);File.WriteAllText(report,"");AppDomain.CurrentDomain.AssemblyResolve+=(s,e)=>new AssemblyName(e.Name).Name=="FrameCut"?Assembly.LoadFrom(Path.Combine(root,"FrameCut.exe")):null;Start();}
 static void Start(){Application app=new Application();try{var c=new Controller(new string[0],root);controller=c;window=c.Window;window.WindowStartupLocation=WindowStartupLocation.Manual;window.Left=-20000;window.Top=-20000;window.ShowInTaskbar=false;window.ShowActivated=false;window.Loaded+=async(s,e)=>{try{await Tests();File.AppendAllText(report,"ALL "+checks+" MULTI-VIDEO UI CHECKS PASSED"+Environment.NewLine);}catch(Exception ex){File.AppendAllText(report,ex+Environment.NewLine);Environment.ExitCode=1;}finally{typeof(Controller).GetField("dirty",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(controller,false);window.Close();}};app.Run(window);}catch(Exception ex){File.AppendAllText(report,ex.ToString());Environment.ExitCode=1;}}
 static async Task Tests(){
  Check(Find<Button>("AddVideo").IsEnabled,"Add-video action available before project creation");bool initialFailed=false;try{await((Controller)controller).AppendVideos(new[]{Path.Combine(dir,"portrait-B.mp4"),Path.Combine(dir,"missing.mp4")});}catch{initialFailed=true;}Check(initialFailed&&Project==null,"Failed initial batch does not create a partial project");await((Controller)controller).AppendVideos(new[]{Path.Combine(dir,"portrait-B.mp4"),Path.Combine(dir,"green-C.mp4")});Check(Project.Sources.Count==2&&Project.Clips.Count==2&&Media.HasAudio,"Multi-selection can create a project with a silent first source");await Open(Path.Combine(root,"示例视频.mp4"));await Jump(37);Click("MarkIn");await Jump(96);Click("MarkOut");await Jump(61);Click("SplitTrack");int[] previous=Project.Clips.SelectMany(c=>new[]{c.In,c.Out}).ToArray();Check(Project.Clips.Count==2,"Existing project has two edited picture clips");
  string b=Path.Combine(dir,"portrait-B.mp4"),greenPath=Path.Combine(dir,"green-C.mp4");await((Controller)controller).AppendVideos(new[]{b,greenPath});Check(Project.Sources.Count==3&&Project.Clips.Count==4,"Two files append without replacing existing project");Check(Project.Clips.Take(2).SelectMany(x=>new[]{x.In,x.Out}).SequenceEqual(previous),"Existing source cuts stay exactly unchanged");Check(Find<ListBox>("ClipList").SelectedIndex==2&&Find<TextBlock>("SourceName").Text=="portrait-B.mp4","First appended source selected for preview");Check(Find<TextBox>("InFrame").Text=="1"&&Find<TextBox>("OutFrame").Text=="30","New source uses its own local frame numbers");
  Check(Project.OriginalAudio.Count==3&&Math.Abs(Project.OriginalAudio[0].Length-2.5)<0.000001&&Math.Abs(Editing.SoundDuration(Project,Media)-4.5)<0.000001,"New original sound joins at edited project end, not unused source tail");double raw;Check(Editing.SoundAt(Project,Media,3.75,out raw)&&Math.Abs(raw-9.25)<0.000001,"Continuous audio preview maps appended C to correct source time");
  await Jump(11);Click("SplitTrack");Check(Project.Clips.Count==5&&Project.Clips[2].Out-Project.Clips[2].In==10,"Appended portrait video can split at local frame 11");var sequence=(SequenceTimeline)Find<Grid>("SequenceHost").Children[0];sequence.DropClip(4,0);Check(Media.PartIndex(Project.Clips[0].In)==2,"Appended green video can move before original footage");Check(Project.Sources[0].Path.EndsWith("示例视频.mp4"),"Picture reorder does not reorder source or sound assets");
  Click("Undo");Click("Undo");Click("Undo");Check(Project.Sources.Count==1&&Project.Clips.Count==2&&Project.Clips.SelectMany(x=>new[]{x.In,x.Out}).SequenceEqual(previous),"Undo append restores complete original project");Click("Redo");Click("Redo");Click("Redo");Check(Project.Sources.Count==3&&Project.Clips.Count==5&&Media.PartIndex(Project.Clips[0].In)==2,"Redo restores imports, cuts and cross-source order");
  sequence.SeekAt(0);await Jump(2);Check(Find<TextBlock>("SourceName").Text=="green-C.mp4"&&Find<TextBlock>("FrameLabel").Text.StartsWith("第 2 / 25"),"Reordered source switch shows correct source and frame counter");
  string saved=Path.Combine(dir,"ui-project.framecut");Editing.Save(Project,saved);await Open(saved);await Jump(2);Check(Project.Sources.Count==3&&Project.Clips.Count==5&&Project.OriginalAudio.Count==3,"Saved multi-video project reopens with all sources and sound sequence");
  var engine=new Engine(Path.Combine(root,"engine"));string output=Path.Combine(dir,"ui-project-export.mp4");await engine.Export(Media,Project,output,true,true,CancellationToken.None,null);MediaInfo exported=await engine.Inspect(output,CancellationToken.None);Check(exported.Frames.Count==115&&Math.Abs(exported.Duration-4.5)<0.002,"Actual edited multi-project exports all 115 selected frames");
  string rawFile=Path.Combine(dir,"ui-project-audio.raw");await engine.Text("ffmpeg","-v error -nostdin -y -i "+Engine.Q(output)+" -map 0:a -ac 1 -ar 48000 -f s16le "+Engine.Q(rawFile),CancellationToken.None);byte[] sound=File.ReadAllBytes(rawFile);Check(Math.Abs(Frequency(sound,9600,28800)-523.25)<4&&Rms(sound,134400,19200)<3&&Math.Abs(Frequency(sound,177600,28800)-880)<4,"Exported sound joins at edited 2.5s end: demo, silent B, then C");
  int sourceCount=Project.Sources.Count,clipCount=Project.Clips.Count;bool failed=false;try{await((Controller)controller).AppendVideos(new[]{b,Path.Combine(dir,"missing.mp4")});}catch{failed=true;}Check(failed&&Project.Sources.Count==sourceCount&&Project.Clips.Count==clipCount,"Failed multi-file import preserves the project atomically");
  bool cancelled=false;Task pending=((Controller)controller).AppendVideos(new[]{b,greenPath});Click("Cancel");try{await pending;}catch(OperationCanceledException){cancelled=true;}Check(cancelled&&Project.Sources.Count==sourceCount&&Project.Clips.Count==clipCount,"Cancelled video addition preserves existing project");
  window.Width=1320;window.Height=870;await Jump(5);await Task.Delay(150);window.UpdateLayout();var visual=(FrameworkElement)window.Content;var bmp=new RenderTargetBitmap((int)Math.Ceiling(visual.ActualWidth),(int)Math.Ceiling(visual.ActualHeight),96,96,PixelFormats.Pbgra32);bmp.Render(visual);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bmp));using(var stream=File.Create(picture))png.Save(stream);Check(new FileInfo(picture).Length>10000,"Multi-source arrangement renders without desktop automation");
  string legacyFile=Path.Combine(dir,"legacy.framecut"),demo=Path.Combine(root,"示例视频.mp4");var legacy=new Project{Version=1,Source=demo,SourceSize=new FileInfo(demo).Length,KeepOriginalAudio=true,Clips={new Clip{Id=1,In=0,Out=192,AudioIn=0,AudioOut=8}}};Editing.Save(legacy,legacyFile);await Open(legacyFile);Check(Project.Version==2&&Project.Sources.Count==1&&Project.Clips.Count==1,"Version-1 single-video project migrates without losing clips");
 }
}


